/* ============================================
   highlight.min.js — Story 3.11 (vendored)

   Hand-rolled HTML/CSS/JS syntax highlighter.
   Token classes: tok-tag, tok-attr, tok-string,
   tok-comment, tok-keyword, tok-number, tok-literal.

   Exposes HT.highlight(code, lang) — returns a
   DocumentFragment (NOT a string) so the caller
   avoids innerHTML XSS risk.

   Zero external dependencies. ~200 LOC. AD-1
   compliant (no CDN, no fonts, no images).

   Author: Handy Tools (Story 3.11)
   ============================================ */

(function () {
  'use strict';

  // -------------------------------------------------
  // Token-table per language. Each entry is a list of
  // {regex, class} pairs; the first match wins for
  // each character position. Comments are stripped
  // first so their content never tokenizes as code.
  // -------------------------------------------------

  var HTML_TOKENS = [
    { re: /<!--[\s\S]*?-->/g, cls: 'tok-comment' },
    { re: /<\/?\w+/g, cls: 'tok-tag' },
    { re: /\s[\w-]+(?==)/g, cls: 'tok-attr' },
    { re: /="[^"]*"/g, cls: 'tok-string' },
    { re: /='[^']*'/g, cls: 'tok-string' }
  ];

  var CSS_TOKENS = [
    { re: /\/\*[\s\S]*?\*\//g, cls: 'tok-comment' },
    { re: /#[0-9a-fA-F]{3,8}\b/g, cls: 'tok-literal' },
    { re: /\b\d+(\.\d+)?(px|em|rem|%|deg|s|ms)?\b/g, cls: 'tok-number' },
    { re: /"[^"]*"|'[^']*'/g, cls: 'tok-string' },
    // Property: foo: ... — match before the colon
    { re: /(\b[a-z-]+)(\s*:)/g, cls: 'tok-attr' },
    // Pseudo / at-rules
    { re: /@[a-z-]+/g, cls: 'tok-keyword' },
    // Selectors (id / class / tag) at start of rule block
    { re: /^[^{}\n]+(?=\{)/gm, cls: 'tok-tag' }
  ];

  var JS_RESERVED = (
    'var let const function return if else for while do switch case ' +
    'break continue throw try catch finally new class extends this ' +
    'super import export from default async await yield of in typeof ' +
    'instanceof void delete null undefined true false'
  );
  var JS_RESERVED_RE = new RegExp('\\b(' + JS_RESERVED.replace(/ /g, '|') + ')\\b', 'g');
  var JS_TOKENS = [
    { re: /\/\*[\s\S]*?\*\//g, cls: 'tok-comment' },
    { re: /\/\/[^\n]*/g, cls: 'tok-comment' },
    { re: /"([^"\\\n]|\\.)*"|'([^'\\\n]|\\.)*'|`([^`\\]|\\.)*`/g, cls: 'tok-string' },
    { re: /\b\d+(\.\d+)?\b/g, cls: 'tok-number' },
    JS_RESERVED_RE ? { re: JS_RESERVED_RE, cls: 'tok-keyword' } : null
  ].filter(Boolean);

  var TOKEN_TABLES = {
    html: HTML_TOKENS,
    css: CSS_TOKENS,
    js: JS_TOKENS
  };

  // -------------------------------------------------
  // Build a DocumentFragment of <span> nodes. Pure
  // DOM construction (no innerHTML) — XSS safe even
  // if `code` contains HTML/JS strings.
  // -------------------------------------------------

  function appendText(parent, text) {
    if (text.length === 0) return;
    parent.appendChild(document.createTextNode(text));
  }

  function appendToken(parent, text, cls) {
    if (text.length === 0) return;
    var span = document.createElement('span');
    span.className = cls;
    span.appendChild(document.createTextNode(text));
    parent.appendChild(span);
  }

  function highlightTo(code, tokens) {
    var frag = document.createDocumentFragment();

    if (!tokens || tokens.length === 0) {
      appendText(frag, code);
      return frag;
    }

    // Build a combined regex from all token sources. Use lastIndex
    // walking to consume code in left-to-right position order. The
    // "first match wins per position" is approximated by sorting
    // matches by start position and breaking ties by source order.
    var combined = new RegExp(
      tokens.map(function (t) {
        return '(?:' + t.re.source + ')';
      }).join('|'),
      'g'
    );

    var lastIndex = 0;
    var m;
    var source = code;
    while ((m = combined.exec(source)) !== null) {
      // Guard against zero-length matches (would loop forever).
      if (m.index === combined.lastIndex) {
        combined.lastIndex += 1;
        continue;
      }
      if (m.index > lastIndex) {
        appendText(frag, source.substring(lastIndex, m.index));
      }
      // Find which capture group matched.
      var cls = null;
      for (var i = 0; i < tokens.length; i++) {
        if (m[i] !== undefined) {
          cls = tokens[i].cls;
          break;
        }
      }
      appendToken(frag, m[0], cls || 'tok-literal');
      lastIndex = m.index + m[0].length;
    }
    if (lastIndex < source.length) {
      appendText(frag, source.substring(lastIndex));
    }
    return frag;
  }

  function highlight(code, lang) {
    var frag = document.createDocumentFragment();
    var tbl = TOKEN_TABLES[(lang || '').toLowerCase()] || null;
    if (!tbl) {
      // Unknown language — just emit plain text.
      appendText(frag, String(code == null ? '' : code));
      return frag;
    }
    return highlightTo(String(code == null ? '' : code), tbl);
  }

  // -------------------------------------------------
  // Public API
  // -------------------------------------------------

  window.HT_highlight = highlight;
  window.HT = window.HT || {};
  window.HT.highlight = highlight;
  // The full token table is also exposed for tests and
  // for any future caller that wants raw regex access.
  window.HT._highlightTokens = TOKEN_TABLES;
})();